eview'):?><p class="preview-banner">Preview publication · Not a live business listing</p><?php endif;?><?php if($p&&$booking):if($enquiry_ready)request_form($slug,$row,$enquiry_error,$sent);else echo '<p class="alert">Booking form unavailable. Please try again shortly.</p>';elseif($homepage):$GLOBALS['homepage_enquiry']=function()use($slug,$row,$enquiry_ready,$enquiry_error,$sent){if($enquiry_ready)enquiry_form($slug,$row['services']??['items'=>[]],$enquiry_error,$sent);else echo '<p class="alert">Enquiry form unavailable. Please try again shortly.</p>';};homepage_render($p,$row['services']??['currency'=>'ZAR','items'=>[]],$row['time_zone'],$base.'/b/'.$slug,$base.'/b/'.$slug.'?hero=1');elseif($p):echo '<p><a class="button" href="'.esc($base.'/b/'.$slug.'?booking=1').'">Request a booking</a></p>';profile_render($p,$row['time_zone'],$base.'/b/'.$slug.'?logo=1');services_render($row['services']??['currency'=>'ZAR','items'=>[]]);if($enquiry_ready)enquiry_form($slug,$row['services']??['items'=>[]],$enquiry_error,$sent);else echo '<p class="alert">Enquiry form unavailable. Please try again shortly.</p>';else:?><article class="public-card"><h1><?=$error?'Please try again shortly':'Page not available'?></h1><p><?=$error?'We could not load this business page right now.':'This business page is unpublished or the address is incorrect.'?></p><a href="<?=esc($base)?>/">FaraiOS home</a></article><?php endif;?></main><?php if(!$homepage):?><footer>Powered by FaraiOS</footer><?php endif;?></body></html>
